  "Borrador": { gl: "Borrador", ca: "Esborrany", en: "Draft" },
  "Registro aceptado": { gl: "Rexistro aceptado", ca: "Registre acceptat", en: "Record accepted" },
  "Registro aceptado con errores": { gl: "Rexistro aceptado con erros", ca: "Registre acceptat amb errors", en: "Record accepted with errors" },
